SELECT r.id || ' — ни в одном этапе' AS detail FROM project_requirements r WHERE r.project_id = $1 AND r.kind = 'FR' AND r.out_of_version = '' AND true AND NOT EXISTS (SELECT 1 FROM project_milestone_requirements m WHERE m.project_id = r.project_id AND m.requirement_id = r.id) UNION ALL SELECT m.requirement_id || ' — сразу в ' || string_agg(m.milestone_id, ' и ' ORDER BY m.milestone_id) FROM project_milestone_requirements m WHERE m.project_id = $1 AND true GROUP BY m.requirement_id HAVING count(DISTINCT m.milestone_id) > 1 ORDER BY 1
